/* Featured is UNLIMITED by default. Optional cap per city + category (a massage shop competes with massage shops, not go-go bars).
   Set a cap once a city/category gets crowded (~25–30 Featured) — or raise the price there instead. PLACEHOLDER: Bangkok massage = 22. */
const FEATURED_CAPS = { bangkok: { massage: 22 } };
const featuredCap = (citySlug, cat) => (FEATURED_CAPS[citySlug] || {})[cat] || null;
const planFor = citySlug => ({ tier: CITY_TIER[citySlug] || 'D', ...PLAN_TIERS[CITY_TIER[citySlug] || 'D'] });


/* ---------- Image resizing ----------
   Originals on images.swanpass.com are full-size uploads (often 250 KB–3 MB). The mockup resizes on the fly with wsrv.nl (free image proxy → WebP).
   Production: turn on Cloudflare Image Transformations for images.swanpass.com and use /cdn-cgi/image/width=W,quality=75,format=auto/<path> (same idea, one helper). */
const rs = (u, w) => !u || /wsrv\.nl/.test(u) || !/^https?:\/\//.test(u) ? u : `https://wsrv.nl/?url=${encodeURIComponent(u.replace(/^https?:\/\//, ''))}&w=${w}&output=webp&q=75`;
LISTINGS.forEach(l => { l.imgFull = l.img; l.img = rs(l.img, 700); });
CITIES.forEach(c => { if (c.img) c.img = rs(c.img, 1400); });
